    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are lists of identifiers
        # A version without pre-release has higher precedence
        if not pre1 and not pre2:
            return 0
        if not pre1:
            return 1  # version without pre-release is greater
        if not pre2:
            return -1  # version with pre-release is less

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare numerically
                if int(id1) < int(id2):
                    return -1
                elif int(id1) > int(id2):
                    return 1
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def compare_versions(v1, v2):
        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        # Compare MAJOR.MINOR.PATCH
        if parsed1[:3] < parsed2[:3]:
            return -1
        elif parsed1[:3] > parsed2[:3]:
            return 1

        # Same core version, compare pre-release
        result = compare_prerelease(parsed1[3], parsed2[3])
        return result

    # Stable sort using the custom comparator
    from functools import cmp_to_key
    return sorted(versions, key=cmp_to_key(compare_versions))

